import csv, numpy as np, math
from math import gcd
from collections import Counter
from scipy.optimize import minimize
from scipy.special import logsumexp, expit
r=list(csv.DictReader(open('responses.csv')))
y=np.array([int(x['rating']) for x in r])
N=len(r)
def rules():
    R={}
    R['odd']={i for i in range(1,101) if i%2}; R['even']={i for i in range(1,101) if i%2==0}
    for k in range(3,13): R[f'm{k}']={i for i in range(1,101) if i%k==0}
    for d in range(10): R[f'e{d}']={i for i in range(1,101) if i%10==d}
    for b in range(2,11): R[f'p{b}']={b**j for j in range(1,8) if b**j<=100}
    R['sq']={i*i for i in range(1,11)}; R['cu']={i**3 for i in range(1,5)}
    R['pr']={i for i in range(2,101) if all(i%j for j in range(2,int(i**.5)+1))}
    return R
RU=rules()
F={k:np.zeros((N,4)) for k in ['d','u','p','c','pr']}
S={k:np.zeros(N) for k in ['sp','dh','ph','run','ev','evd','mem','run_nm']}
for i,x in enumerate(r):
    ex=[int(v) for v in x['number_set'].split(',')]; t=int(x['target']); n=len(ex)
    for k,e in enumerate(ex):
        F['d'][i,k]=abs(t-e)/10; F['u'][i,k]=t%10!=e%10; F['p'][i,k]=t%2!=e%2; F['c'][i,k]=gcd(t,e)==1; F['pr'][i,k]=1
    if n>1:
        S['sp'][i]=(max(ex)-min(ex))/100; S['dh'][i]=(max(Counter(e%10 for e in ex).values())-1)/(n-1); S['ph'][i]=(max(Counter(e%2 for e in ex).values())-1)/(n-1)
    else: S['sp'][i]=S['dh'][i]=S['ph'][i]=.5
    run=n>=3 and len({e%10 for e in ex})==1
    S['run'][i]=run; S['run_nm'][i]=run and t%10!=ex[0]%10
    cons=[R for R in RU.values() if all(e in R for e in ex)]
    sm=min(len(R) for R in cons) if cons else 100
    S['ev'][i]=(n-1)*math.log(100/sm)/math.log(100)
    best=min((R for R in cons), key=len) if cons else None
    S['mem'][i]=0 if best is None else (1 if t in best else -1)
    S['evd'][i]=S['ev'][i]*S['mem'][i]
def nll(th,extra):
    lcm,lcu,st,ht,cp,cf,a,b=th[:8]; g=th[8:]
    cm=np.exp(lcm-st*S['sp'])[:,None]; cu=np.exp(lcu+ht*S['dh'])[:,None]; cpp=(abs(cp)*S['ph'])[:,None]
    ls=-cm*F['d']-cu*F['u']-cpp*F['p']-abs(cf)*F['c']; ls=np.where(F['pr']>0,ls,-1e3)
    L=logsumexp(ls,axis=1); z=a+abs(b)*L
    for gi,e in zip(g,extra): z=z+gi*S[e]
    p=np.clip(expit(z),1e-9,1-1e-9); return -np.sum(y*np.log(p)+(1-y)*np.log(1-p))
th0=np.array([0,1,0,0,1,1,0,1.])
for extra in [[],['run'],['ev'],['evd'],['run','evd'],['run_nm']]:
    best=None
    for s in range(4):
        x0=np.r_[th0+np.random.default_rng(s).normal(0,.3,8)*(s>0),np.zeros(len(extra))]
        o=minimize(nll,x0,args=(extra,),method='L-BFGS-B')
        if best is None or o.fun<best.fun: best=o
    print(extra,round(best.fun,1),np.round(best.x,2))
